#!/bin/bash
# run_cpu_direct.sh -- the CPU-direct checks of the model on their own (HAS_CPU_DIRECT=1, RTL revision 2), with a summary table.
#
# The CPU programs the SAURIA, GVU and DMA blocks through their register files (docs/CPU_DIRECT_GUIDE.md); the testbench
# tools/has/tb_has_npu_top plays the CPU: it replays a program (mmio.txt: W = register write, P = poll a register until a value,
# K = compare a DRAM region with the golden image) through the host port. Each program is generated by a script of this directory,
# most of them from a run of the data flow controller of the model on the same work (HAS_CPU_DIRECT_DUMP), so the golden is the
# controller path. Programs, environments and pass criteria are those of the CPU-direct items of tools/has/regress_gvu.sh.
#
# Run from the repository root on the Linux machine (g++, SystemC under /usr, python3 with numpy):
#   bash tools/has/cpu_direct/run_cpu_direct.sh [out dir]
# Output: one log per test in <out dir> (<test>.log, and <test>.gen.log for the generator), the table on stdout and in
# <out dir>/summary.txt. A check passes only when every condition of it holds (not only the RESULT line); a negative control passes
# when the run fails exactly as expected. Exit status = number of failed checks.
# Verification by flow: at the end tools/has/verify_flows.py --only CPU_ writes <out dir>/flows/CPU_*.log and SUMMARY.md: the steps of
# CPU_DIRECT_GUIDE.md section 4, each with its checks, reference kind (R RTL / S specification / M model only), result, evidence line and
# verdict (format of docs FLOW_VERIFICATION.md). The RTL references are the stored runs of tools/has/cpu_direct/rtl_cpu_runs.txt.
# Evidence: every CPU program run writes the DRAM image the CPU left (<program dir>/dram_snapshot.bin, FE_SNAPSHOT_DIR of the
# testbench); evidence_cpu_direct.py then writes one evidence sheet per test (input, CPU program, output against the golden region by
# region) into <out dir>/evidence/ (INDEX.md first).
set -u
# The reference values below are those of regress_gvu.sh, which runs with these knobs off; an entry that needs a knob sets it itself.
export HAS_GVU_TOP=0 HAS_GVU_STALL=0 HAS_GVU_ELEM_CLK=0 HAS_GVU_REGS=0 HAS_GVU_AGU_ND=0
export HAS_GVU_AVG=0 HAS_GVU_SOFTMAX=0 HAS_GVU_FA=0 HAS_GVU_LN=0
export HAS_DMA_TENSOR=0 HAS_DMA_ND=0
export HAS_DMA_RESHAPE=0 HAS_DMA_ND_MERGE=0 HAS_OUT_TRANSPOSE=0 HAS_HOST=v45 HAS_DMA_DFC1D_FIRST=19 HAS_DMA_DFC1D_TAIL=7
OUT=${1:-/var/tmp/npu_safe/cpu_direct_run}
export LD_LIBRARY_PATH=/usr/lib/x86_64-linux-gnu:${LD_LIBRARY_PATH:-}
mkdir -p "$OUT"
NEOENV="-u HAS_GVU_TOP -u HAS_GVU_STALL -u HAS_GVU_ELEM_CLK -u HAS_GVU_REGS -u HAS_GVU_AGU_ND -u HAS_GVU_AVG -u HAS_GVU_SOFTMAX -u HAS_GVU_FA -u HAS_GVU_LN -u HAS_DMA_TENSOR -u HAS_DMA_ND -u HAS_PROFILE"
RELENV="-u HAS_DMA_RESHAPE -u HAS_DMA_ND_MERGE -u HAS_OUT_TRANSPOSE -u HAS_HOST -u HAS_DMA_DFC1D_FIRST -u HAS_DMA_DFC1D_TAIL"
CPUENV="HAS_CPU_DIRECT=1 HAS_NEO_REV=2 HAS_GVU_REGS=1 HAS_GVU_REGS_NEO=1 HAS_GVU_AGU_ND=0"
GEMMENV="HAS_PROFILE=neo_as_rtl HAS_NEO_REV=2 HAS_CPU_DIRECT=1"
TB="$OUT/tb_has_npu_top"
T0=$(date +%s)

# ---- table: res <exit status of the check> <test> <what is checked> [log for the numbers]
n=0; ok=0; bad=0; ROWS=()
nums() {   # the numbers of a testbench log: tensors / bytes / bad bytes of the RESULT line, cycles, SAURIA starts and soft resets, DMA commands
  local f=$1 r c s sr d
  [ -f "$f" ] || { echo "-"; return; }
  r=$(grep -h "RESULT:" "$f" | tail -1 | sed -n 's/.*RESULT: \([A-Z]*\) (steps [0-9]*, tensors \([0-9]*\), elements \([0-9]*\), bad tensors \([0-9]*\), bad elements \([0-9]*\).*/\1: regions \2, bytes \3, bad regions \4, bad bytes \5/p')
  c=$(grep -ho "sim cycles [0-9]*" "$f" | tail -1 | grep -o "[0-9]*$")
  s=$(grep -ho "SAURIA: starts [0-9]*" "$f" | head -1 | grep -o "[0-9]*$")
  sr=$(grep -ho "soft resets [0-9]*" "$f" | head -1 | grep -o "[0-9]*$")
  d=$(grep -ho "1-D DMA commands [0-9]*" "$f" | head -1 | grep -o "[0-9]*$")
  echo "${r:-no RESULT line}${c:+; cycles $c}${s:+; SAURIA starts $s}${sr:+, soft resets $sr}${d:+; DMA commands $d}"
}
res() {
  local v=PASS; n=$((n + 1))
  if [ "$1" = 0 ]; then ok=$((ok + 1)); else v=FAIL; bad=$((bad + 1)); fi
  local row; row=$(printf "%3d  %-4s  %-17s %s" "$n" "$v" "$2" "$3")
  ROWS+=("$row")
  [ -n "${4:-}" ] && ROWS+=("$(printf "%29s%s" "" "$(nums "$4")")")
  echo "$row"
}

echo "== CPU-direct checks of the model, out dir $OUT"
# ---- 1. testbench and the programs of the data flow controller the CPU programs are taken from
nice -n 19 g++ -std=c++17 -O2 -DSAURIA_DEBUG=0 -DSAURIA_CORE_BACKEND_RTL_REF -DFX1_A3_SRAM_BACKDOOR_LOAD -I. -I/usr/include -DFX1_NO_PERF \
  tools/has/tb_has_npu_top.cpp -lsystemc -lm -pthread -o "$TB" 2> "$OUT/top.build.log"
res $? build "tb_has_npu_top builds (the testbench that plays the CPU)"
rm -rf "$OUT/ref_gate" "$OUT/ref_gate_mp"
python3 tools/has/make_ref_gate.py "$OUT/ref_gate" > /dev/null && python3 tools/has/ref_program.py "$OUT/ref_gate" --image "$OUT/ref_gate/dram_init.bin" \
  --write-ref "$OUT/ref_gate/dram_golden.bin" > /dev/null 2>&1; [ -s "$OUT/ref_gate/mmio.txt" ] && [ -s "$OUT/ref_gate/dram_golden.bin" ]
res $? ref_gate "source program of the controller (GEMM, ADD): generated with its golden"
python3 tools/has/make_ref_gate_mp.py "$OUT/ref_gate_mp" > /dev/null && { python3 tools/has/ref_program.py "$OUT/ref_gate_mp" --image "$OUT/ref_gate_mp/dram_init.bin" \
  --write-ref "$OUT/ref_gate_mp/dram_golden.bin" > /dev/null 2>&1; [ -s "$OUT/ref_gate_mp/dram_golden.bin" ]; }
res $? ref_gate_mp "source program with max pools: generated with its golden"
env $NEOENV HAS_PROFILE=neo "$TB" "$OUT/ref_gate" > "$OUT/gate_prof_neo.log" 2>&1
grep -q "RESULT: PASS" "$OUT/gate_prof_neo.log" && grep -q "sim cycles 39562" "$OUT/gate_prof_neo.log"
res $? gate_prof_neo "controller path, profile neo, knob off: PASS, 39 562 cycles" "$OUT/gate_prof_neo.log"

# ---- 2. DMA tensor register file (HAS_DMA_OPGEN): copy, fill, 2-D pad, upsample programmed by the CPU
python3 tools/has/opgen_sim/opgen_cases.py gen "$OUT/opgen_cases" > "$OUT/opgen_gen.log" 2>&1
res $? opgen_cases "DMA tensor: 11 groups of cases and their independent reference"
nice -n 19 g++ -std=c++17 -O1 -I. -I/usr/include tools/has/opgen_sim/tb_opgen_seq.cpp -o "$OUT/tb_opgen_seq" 2> "$OUT/tb_opgen_seq.build.log"
res $? build_opgen "tb_opgen_seq builds"
"$OUT/tb_opgen_seq" "$OUT/opgen_cases" > "$OUT/opgen_seq.log" 2>&1
grep -q "RESULT: 0 groups with a mismatch" "$OUT/opgen_seq.log" && [ "$(grep -c "PASS  bytes_bad=0 seg_bad=0" "$OUT/opgen_seq.log")" = 11 ]
res $? opgen_seq "DMA tensor model vs reference: bytes, segments, register reads, 11 of 11 groups"
python3 tools/has/opgen_sim/make_opgen_e2e.py "$OUT/opgen_e2e" > /dev/null 2>&1
HAS_DMA_OPGEN=1 HAS_NEO_REV=2 HAS_DMA_TENSOR=1 FE_SNAPSHOT_DIR="$OUT/opgen_e2e" timeout 600 "$TB" "$OUT/opgen_e2e" > "$OUT/opgen_e2e.log" 2>&1
grep -q "RESULT: PASS (steps 1, tensors 8" "$OUT/opgen_e2e.log" && [ "$(grep -c "\[OPGEN\] region.*bad=0 PASS" "$OUT/opgen_e2e.log")" = 7 ]
res $? opgen_e2e "DMA tensor through the host port: 1 COPY + 7 descriptors exact vs golden DRAM" "$OUT/opgen_e2e.log"

# ---- 3. one-dimensional DMA, one core run, max pool, RESIDUAL
rm -rf "$OUT"/cpu_dma "$OUT"/cpu_core "$OUT"/cpu_pool "$OUT"/cpu_res "$OUT"/cpu_res_sub "$OUT"/cpu_dump_core "$OUT"/cpu_dump_pool; mkdir -p "$OUT/cpu_dump_core" "$OUT/cpu_dump_pool"
python3 -I tools/has/cpu_direct/mk_cpu_dma.py "$OUT/cpu_dma" > "$OUT/cpu_dma.gen.log" 2>&1 && env $NEOENV $RELENV $CPUENV FE_SNAPSHOT_DIR="$OUT/cpu_dma" timeout 600 "$TB" "$OUT/cpu_dma" > "$OUT/cpu_dma.log" 2> "$OUT/cpu_dma.err"
grep -q "RESULT: PASS (steps 0, tensors 11" "$OUT/cpu_dma.log" && grep -q "1-D DMA commands 19 (write-zero 1), bytes 102562, cycles 6607, not executed 1" "$OUT/cpu_dma.log" \
  && [ "$(grep -c "DMA command not executed" "$OUT/cpu_dma.err")" = 1 ]
res $? cpu_dma "1-D DMA to/from SRAM A/B/C, vbank0/1/2, sbank; unaligned; write-zero" "$OUT/cpu_dma.log"
env $NEOENV $RELENV HAS_CPU_DIRECT=1 HAS_NEO_REV=2 HAS_CPU_DIRECT_DUMP="$OUT/cpu_dump_core" timeout 600 "$TB" "$OUT/ref_gate" --profile legacy > "$OUT/cpu_dump_core.log" 2>&1 \
  && grep -q "RESULT: PASS" "$OUT/cpu_dump_core.log" && python3 -I tools/has/cpu_direct/mk_cpu_core.py "$OUT/cpu_dump_core" "$OUT/cpu_core" > "$OUT/cpu_core.gen.log" 2>&1
res $? cpu_core_gen "first core run of the controller dumped, CPU program (29 words) made"
DFC_CORE=$(grep -o 'dfc_core_cycles [0-9]*' "$OUT/cpu_core.gen.log" 2>/dev/null | cut -d' ' -f2)
env $NEOENV $RELENV $CPUENV FE_SNAPSHOT_DIR="$OUT/cpu_core" timeout 600 "$TB" "$OUT/cpu_core" > "$OUT/cpu_core.log" 2>&1
grep -q "RESULT: PASS (steps 0, tensors 1, elements 9216" "$OUT/cpu_core.log" && grep -q "SAURIA: starts 1 (ignored 0, failed 0), cycles ${DFC_CORE:-x}," "$OUT/cpu_core.log" \
  && grep -q "decode differs 0, value wider than its register 0" "$OUT/cpu_core.log"
res $? cpu_core "one core run by the CPU: SRAM C 9 216 B exact, core cycles = controller ($DFC_CORE)" "$OUT/cpu_core.log"
env $NEOENV $RELENV $CPUENV HAS_CPU_DIRECT_DUMP="$OUT/cpu_dump_pool" timeout 600 "$TB" "$OUT/ref_gate_mp" > "$OUT/cpu_dump_pool.log" 2>&1 \
  && grep -q "RESULT: PASS" "$OUT/cpu_dump_pool.log" && python3 -I tools/has/cpu_direct/mk_cpu_pool.py "$OUT/cpu_dump_pool" "$OUT/cpu_pool" --valid > "$OUT/cpu_pool.gen.log" 2>&1
res $? cpu_pool_gen "first max pool of the controller dumped, CPU program made"
DFC_UNIT=$(grep -o 'dfc_unit_cycles [0-9]*' "$OUT/cpu_pool.gen.log" 2>/dev/null | cut -d' ' -f2)
env $NEOENV $RELENV $CPUENV FE_SNAPSHOT_DIR="$OUT/cpu_pool" timeout 600 "$TB" "$OUT/cpu_pool" > "$OUT/cpu_pool.log" 2>&1
grep -q "RESULT: PASS (steps 0, tensors 192, elements 2304" "$OUT/cpu_pool.log" && grep -q "unit edges driven by the CPU registers ${DFC_UNIT:-x}, writes dropped 11" "$OUT/cpu_pool.log"
res $? cpu_pool "max pool by the CPU: 192 rows exact, unit cycles = controller ($DFC_UNIT)" "$OUT/cpu_pool.log"
for s in 0 1; do d=cpu_res; [ $s = 1 ] && d=cpu_res_sub
  python3 -I tools/has/cpu_direct/mk_cpu_res.py "$OUT/$d" --sub $s > "$OUT/$d.gen.log" 2>&1 && env $NEOENV $RELENV $CPUENV FE_SNAPSHOT_DIR="$OUT/$d" timeout 600 "$TB" "$OUT/$d" > "$OUT/$d.log" 2>&1; done
grep -q "RESULT: PASS (steps 0, tensors 1, elements 2048" "$OUT/cpu_res.log" && grep -q "unit edges driven by the CPU registers 80, writes dropped 0" "$OUT/cpu_res.log"
res $? cpu_res "RESIDUAL add (bias, shift, zero point; RTL formula): 64 rows, 80 cycles" "$OUT/cpu_res.log"
grep -q "RESULT: PASS (steps 0, tensors 1, elements 2048" "$OUT/cpu_res_sub.log" && grep -q "unit edges driven by the CPU registers 80, writes dropped 0" "$OUT/cpu_res_sub.log"
res $? cpu_res_sub "RESIDUAL subtract: 64 rows exact, 80 cycles" "$OUT/cpu_res_sub.log"

# ---- 4. GEMM_FUSED (core stream into the vector unit), soft reset, status registers
rm -rf "$OUT"/gemm_gate32 "$OUT"/gemm_gate64 "$OUT"/gemm_dump32 "$OUT"/gemm_dump64 "$OUT"/cpu_gemm_3t "$OUT"/cpu_gemm_mc "$OUT"/cpu_gemm_nosoft "$OUT"/cpu_core_st "$OUT"/cpu_core_soft
for w in 32 64; do mkdir -p "$OUT/gemm_dump$w"
  python3 -I tools/has/cpu_direct/mk_gemm_gate.py "$OUT/gemm_gate$w" --w $w > "$OUT/gemm_gate$w.gen.log" 2>&1 \
    && { [ -s "$OUT/gemm_gate$w/dram_golden.bin" ] || cp "$OUT/gemm_gate$w/dram_init.bin" "$OUT/gemm_gate$w/dram_golden.bin"; } \
    && env $NEOENV $RELENV $GEMMENV HAS_CPU_DIRECT_DUMP="$OUT/gemm_dump$w" timeout 600 "$TB" "$OUT/gemm_gate$w" > "$OUT/gemm_dump$w.log" 2>&1; done
python3 -I tools/has/cpu_direct/mk_cpu_gemm.py "$OUT/gemm_dump32/gemm_L0" "$OUT/cpu_gemm_3t" > "$OUT/cpu_gemm_3t.gen.log" 2>&1
grep -q "^calls 3 beats 96 out_bytes 3072 .*RTL program written" "$OUT/cpu_gemm_3t.gen.log"
res $? cpu_gemm_3t_gen "GEMM layer of 3 tiles (1 context/call) dumped, CPU + RTL program made"
python3 -I tools/has/cpu_direct/mk_cpu_gemm.py "$OUT/gemm_dump64/gemm_L0" "$OUT/cpu_gemm_mc" > "$OUT/cpu_gemm_mc.gen.log" 2>&1
grep -q "^calls 3 beats 192 out_bytes 6144 .*RTL program NOT written" "$OUT/cpu_gemm_mc.gen.log"
res $? cpu_gemm_mc_gen "GEMM layer of 3 tiles (2 contexts/call) dumped, CPU program made"
env $NEOENV $RELENV $GEMMENV FE_SNAPSHOT_DIR="$OUT/cpu_gemm_3t" timeout 600 "$TB" "$OUT/cpu_gemm_3t" > "$OUT/cpu_gemm_3t.log" 2>&1
grep -q "RESULT: PASS (steps 0, tensors 1, elements 3072" "$OUT/cpu_gemm_3t.log" && grep -q "3072 B -> bad=0 PASS" "$OUT/cpu_gemm_3t.log" \
  && grep -q "SAURIA: starts 3 (ignored 0, failed 0)" "$OUT/cpu_gemm_3t.log" && grep -q "soft resets 2;" "$OUT/cpu_gemm_3t.log" \
  && grep -q "GEMM: runs 1, result rows into vbank2 96, scale / shift reads beyond the sbank 0" "$OUT/cpu_gemm_3t.log"
res $? cpu_gemm_3t "GEMM_FUSED by the CPU: 96 rows = controller, 3 starts, 2 soft resets" "$OUT/cpu_gemm_3t.log"
env $NEOENV $RELENV $GEMMENV FE_SNAPSHOT_DIR="$OUT/cpu_gemm_mc" timeout 600 "$TB" "$OUT/cpu_gemm_mc" > "$OUT/cpu_gemm_mc.log" 2>&1
grep -q "RESULT: PASS (steps 0, tensors 1, elements 6144" "$OUT/cpu_gemm_mc.log" && grep -q "6144 B -> bad=0 PASS" "$OUT/cpu_gemm_mc.log" \
  && grep -q "SAURIA: starts 3 (ignored 0, failed 0)" "$OUT/cpu_gemm_mc.log" && grep -q "GEMM: runs 1, result rows into vbank2 192," "$OUT/cpu_gemm_mc.log"
res $? cpu_gemm_mc "GEMM_FUSED by the CPU, 2 contexts/call: 192 rows exact" "$OUT/cpu_gemm_mc.log"
mkdir -p "$OUT/cpu_gemm_nosoft"; cp "$OUT/cpu_gemm_3t/dram_init.bin" "$OUT/cpu_gemm_3t/dram_golden.bin" "$OUT/cpu_gemm_nosoft/" 2>/dev/null
grep -v "^W 0x00011000 0x800000" "$OUT/cpu_gemm_3t/mmio.txt" > "$OUT/cpu_gemm_nosoft/mmio.txt" 2>/dev/null
env $NEOENV $RELENV $GEMMENV FE_SNAPSHOT_DIR="$OUT/cpu_gemm_nosoft" timeout 600 "$TB" "$OUT/cpu_gemm_nosoft" > "$OUT/cpu_gemm_nosoft.log" 2> "$OUT/cpu_gemm_nosoft.err"
grep -q "RESULT: PASS (steps 0, tensors 1, elements 3072" "$OUT/cpu_gemm_nosoft.log" && grep -q "SAURIA: 2 START(s) without a soft reset" "$OUT/cpu_gemm_nosoft.log" \
  && [ "$(grep -c "START without a soft reset" "$OUT/cpu_gemm_nosoft.err")" = 1 ]
res $? cpu_gemm_nosoft "FPGA rule: soft resets removed -> 2 STARTs flagged, 1 message" "$OUT/cpu_gemm_nosoft.log"
python3 -I tools/has/cpu_direct/mk_cpu_core_variants.py "$OUT/cpu_core" "$OUT/cpu_core_st" "$OUT/cpu_core_soft" > /dev/null 2>&1
env $NEOENV $RELENV $CPUENV FE_SNAPSHOT_DIR="$OUT/cpu_core_st" timeout 600 "$TB" "$OUT/cpu_core_st" > "$OUT/cpu_core_st.log" 2> "$OUT/cpu_core_st.err"
grep -q "RESULT: PASS (steps 0, tensors 1, elements 9216" "$OUT/cpu_core_st.log" \
  && grep -q "SAURIA status: reads 6, last status 0x0 cycles ${DFC_CORE:-x} stalls [0-9]* version 0x00772020" "$OUT/cpu_core_st.log" \
  && [ "$(grep -c "auto restart bit" "$OUT/cpu_core_st.err")" = 1 ]
res $? cpu_core_st "SAURIA status registers read back: version, cycle counter = controller" "$OUT/cpu_core_st.log"
env $NEOENV $RELENV $CPUENV FE_SNAPSHOT_DIR="$OUT/cpu_core_soft" timeout 600 "$TB" "$OUT/cpu_core_soft" > "$OUT/cpu_core_soft.log" 2> "$OUT/cpu_core_soft.err"
grep -q "RESULT: PASS (steps 0, tensors 1, elements 9216" "$OUT/cpu_core_soft.log" && grep -q "SAURIA: starts 2 (ignored 0, failed 0)" "$OUT/cpu_core_soft.log" \
  && grep -q "soft resets 1;" "$OUT/cpu_core_soft.log" && ! grep -q "without a soft reset" "$OUT/cpu_core_soft.err"
res $? cpu_core_soft "soft reset right after START, run again: 9 216 B exact" "$OUT/cpu_core_soft.log"
env $NEOENV HAS_PROFILE=neo HAS_CPU_DIRECT=1 "$TB" "$OUT/ref_gate" > "$OUT/gate_prof_neo_cpu.log" 2>&1; cmp -s "$OUT/gate_prof_neo.log" "$OUT/gate_prof_neo_cpu.log"
res $? knob_no_effect "knob on, no CPU access: controller log identical to knob off"

# ---- 5. two layers chained through DRAM, as firmware for a whole network runs them; negative control without the table reset
rm -rf "$OUT"/chain_gate "$OUT"/chain_dump "$OUT"/cpu_chain "$OUT"/cpu_chain_nr; mkdir -p "$OUT/chain_dump" "$OUT/cpu_chain_nr"
python3 -I tools/has/cpu_direct/mk_cpu_chain.py gate "$OUT/chain_gate" > "$OUT/chain_gate.gen.log" 2>&1 \
  && env $NEOENV $RELENV $GEMMENV HAS_CPU_DIRECT_DUMP="$OUT/chain_dump" timeout 600 "$TB" "$OUT/chain_gate" > "$OUT/chain_dump.log" 2>&1
python3 -I tools/has/cpu_direct/mk_cpu_chain.py cpu "$OUT/chain_dump" "$OUT/cpu_chain" > "$OUT/cpu_chain.gen.log" 2>&1
grep -q "^layers 2 starts 4 beats 64+64 residual_rows 64 bytes_checked 6144 " "$OUT/cpu_chain.gen.log"
res $? cpu_chain_gen "2 GEMM layers of the controller dumped, chained CPU program made"
env $NEOENV $RELENV $GEMMENV FE_SNAPSHOT_DIR="$OUT/cpu_chain" timeout 600 "$TB" "$OUT/cpu_chain" > "$OUT/cpu_chain.log" 2> "$OUT/cpu_chain.err"
grep -q "RESULT: PASS (steps 0, tensors 3, elements 6144, bad tensors 0, bad elements 0" "$OUT/cpu_chain.log" && grep -q "SAURIA: starts 4 (ignored 0, failed 0)" "$OUT/cpu_chain.log" \
  && grep -q "soft resets 3;" "$OUT/cpu_chain.log" && grep -q "GEMM: runs 2, result rows into vbank2 128," "$OUT/cpu_chain.log" && ! grep -q "without a soft reset" "$OUT/cpu_chain.err"
res $? cpu_chain "layer 0 -> DRAM -> layer 1, then RESIDUAL: 3 regions exact" "$OUT/cpu_chain.log"
cp "$OUT"/cpu_chain/dram_*.bin "$OUT/cpu_chain_nr/" 2>/dev/null; grep -v "^W 0x00012008 0x1" "$OUT/cpu_chain/mmio.txt" > "$OUT/cpu_chain_nr/mmio.txt" 2>/dev/null
env $NEOENV $RELENV $GEMMENV FE_SNAPSHOT_DIR="$OUT/cpu_chain_nr" timeout 600 "$TB" "$OUT/cpu_chain_nr" > "$OUT/cpu_chain_nr.log" 2>&1
grep -q "RESULT: FAIL (steps 0, tensors 3, elements 6144, bad tensors 2, bad elements 4096" "$OUT/cpu_chain_nr.log"
res $? cpu_chain_nr "NEGATIVE CONTROL: table reset removed -> must FAIL, 4 096 B bad" "$OUT/cpu_chain_nr.log"

# ---- summary
T1=$(date +%s)
{
  echo
  echo "== CPU-direct checks of the model: summary ($(date '+%F %T'), $((T1 - T0)) s, out dir $OUT)"
  printf "%3s  %-4s  %-17s %s\n" "No" "Res" "Test" "What is checked  /  numbers from the log"
  printf -- "---------------------------------------------------------------------------------------------------------\n"
  for r in "${ROWS[@]}"; do echo "$r"; done
  printf -- "---------------------------------------------------------------------------------------------------------\n"
  echo "RESULT: $ok of $n checks pass, $bad fail"
  echo "A check passes when every condition of it holds (RESULT line, counts, cycles); a NEGATIVE CONTROL passes when its run fails as expected."
} | tee "$OUT/summary.txt"
# Verification by flow (docs FLOW_VERIFICATION.md): the CPU_* flows of verify_flows.py read the logs above, step by step, with the
# reference of every check (R RTL simulation, S specification, M model only) and the log line it was read from.
echo
echo "== Verification by flow (tools/has/verify_flows.py --only CPU_): one log per flow in $OUT/flows"
python3 -I tools/has/verify_flows.py "$OUT" --only CPU_ | tee "$OUT/flows.log" || bad=$((bad + 1))
python3 -I tools/has/cpu_direct/evidence_cpu_direct.py "$OUT" > "$OUT/evidence.log" 2>&1 && echo "evidence sheets per test: $OUT/evidence/INDEX.md" \
  || { echo "evidence sheets: FAILED (see $OUT/evidence.log)"; bad=$((bad + 1)); }
exit $bad
